f = "app/views/pwa/service_worker.js.erb"
s = File.read(f)
s.sub!(%(self.addEventListener("activate", (event) => {\n  event.waitUntil(self.clients.claim())\n})\n), <<~JS)
self.addEventListener("activate", (event) => {
  event.waitUntil(self.clients.claim())
})

// Push notifications
self.addEventListener("push", (event) => {
  const { title, body, path, tag, badge } = event.data?.json() ?? {}

  if (title) {
    event.waitUntil(Promise.all([
      self.registration.showNotification(title, {
        body,
        tag,
        renotify: Boolean(tag),
        icon: "/app-icon-192.png",
        data: { path }
      }),
      updateAppBadge(badge)
    ]))
  }
})

self.addEventListener("notificationclick", (event) => {
  event.notification.close()

  const url = sameOriginUrl(event.notification.data?.path)
  event.waitUntil(openOrFocusWindow(url))
})

function sameOriginUrl(path) {
  const url = new URL(path || "/", self.location.origin)
  return url.origin === self.location.origin ? url.href : self.location.origin
}

async function openOrFocusWindow(url) {
  const windows = await self.clients.matchAll({ type: "window", includeUncontrolled: true })
  const existing = windows.find((client) => client.url === url)

  if (existing) {
    return existing.focus()
  } else {
    return self.clients.openWindow(url)
  }
}

async function updateAppBadge(count) {
  if (Number.isInteger(count) && "setAppBadge" in self.navigator) {
    try {
      await (count > 0 ? self.navigator.setAppBadge(count) : self.navigator.clearAppBadge())
    } catch {
      // Badging isn't allowed everywhere; the notification itself still shows.
    }
  }
}
